import asrAddonLogging from '@qvac/asr-ggml/addonLogging';
import ASRGgml from '@qvac/asr-ggml';
import { definePlugin, defineHandler, defineDuplexHandler, transcribeRequestSchema, transcribeResponseSchema, transcribeStreamRequestSchema, transcribeStreamResponseSchema, ModelType, parakeetLoadConfigSchema, LEGACY_PARAKEET_ONNX_MODEL_CONFIG_FIELDS, ADDON_ASR } from '../../../../schemas/index.js';
import { ModelLoadFailedError, TranscriptionFailedError, LegacyParakeetModelDeprecatedError } from '../../../../utils/errors-server.js';
import { transcribe, transcribeStream } from '../../../../server/bare/ops/transcribe.js';
import { attachModelExecutionMs } from '../../../../profiling/model-execution.js';
import { buildParakeetEngineConfig } from '../../../../server/bare/plugins/asr-ggml/config.js';
import { createAsrModelLogger } from '../../../../server/bare/plugins/asr-ggml/logging.js';
function resolveParakeetConfig(cfg) {
    const cfgRecord = cfg;
    const legacyFields = LEGACY_PARAKEET_ONNX_MODEL_CONFIG_FIELDS.filter((name) => cfgRecord[name] !== undefined);
    if (legacyFields.length > 0) {
        throw new LegacyParakeetModelDeprecatedError(legacyFields);
    }
    return Promise.resolve({ config: cfg });
}
function createParakeetModel(params) {
    const config = (params.modelConfig ?? {});
    const modelPath = params.modelPath;
    if (!modelPath) {
        throw new ModelLoadFailedError('Parakeet requires a GGUF model source');
    }
    const logger = createAsrModelLogger(params.modelId, ModelType.parakeetTranscription);
    const model = new ASRGgml({
        files: { model: modelPath },
        config: buildParakeetEngineConfig(config),
        enableStats: true,
        logger
    });
    return { model };
}
export const parakeetPlugin = definePlugin({
    modelType: ModelType.parakeetTranscription,
    displayName: 'Parakeet (NVIDIA NeMo GGML)',
    addonPackage: ADDON_ASR,
    loadConfigSchema: parakeetLoadConfigSchema,
    resolveConfig(cfg) {
        return resolveParakeetConfig(cfg);
    },
    createModel(params) {
        return createParakeetModel(params);
    },
    handlers: {
        transcribe: defineHandler({
            requestSchema: transcribeRequestSchema,
            responseSchema: transcribeResponseSchema,
            streaming: true,
            cancel: { scope: 'model', hard: true },
            handler: async function* (request) {
                if (request.metadata === true) {
                    throw new TranscriptionFailedError(`Parakeet transcription does not support metadata: true; only the whisper engine emits per-segment metadata. Use a whisper model to receive segments.`);
                }
                const stream = transcribe({
                    modelId: request.modelId,
                    audioChunk: request.audioChunk,
                    prompt: request.prompt
                }, request.requestId);
                try {
                    let result = await stream.next();
                    while (!result.done) {
                        yield {
                            type: 'transcribe',
                            text: result.value
                        };
                        result = await stream.next();
                    }
                    const { modelExecutionMs, stats } = result.value;
                    yield attachModelExecutionMs({
                        type: 'transcribe',
                        text: '',
                        done: true,
                        ...(stats && { stats })
                    }, modelExecutionMs);
                }
                finally {
                    await stream.return?.(undefined);
                }
            }
        }),
        transcribeStream: defineDuplexHandler({
            requestSchema: transcribeStreamRequestSchema,
            responseSchema: transcribeStreamResponseSchema,
            streaming: true,
            duplex: true,
            cancel: { scope: 'model', hard: true },
            // TODO(QVAC-17869-followup): wire `AbortSignal` through the duplex
            // handler signature so the worker learns about consumer disconnects
            // without depending on `inputStream.end()` (which does not fire if the
            // client drops packets while TCP stays alive). Under sustained slow
            // consumers, `runStreaming` may buffer between the server generator and
            // the duplex RPC writer — backpressure is not yet characterised. Pair
            // the fix with request-lifecycle `cancel({ requestId })` routing.
            handler: async function* (request, inputStream) {
                if (request.metadata === true) {
                    throw new TranscriptionFailedError(`Parakeet transcribeStream does not support metadata: true; only the whisper engine emits per-segment metadata.`);
                }
                const streamOpts = {
                    ...(request.parakeetStreamingConfig && {
                        parakeetStreamingConfig: request.parakeetStreamingConfig
                    })
                };
                const iterator = transcribeStream(request.modelId, inputStream, undefined, false, streamOpts, request.requestId);
                for await (const value of iterator) {
                    if (typeof value === 'object' && value !== null && 'type' in value) {
                        if (value.type === 'endOfTurn') {
                            yield {
                                type: 'transcribeStream',
                                endOfTurn: { source: 'parakeet' }
                            };
                        }
                        continue;
                    }
                    yield {
                        type: 'transcribeStream',
                        text: value
                    };
                }
                yield {
                    type: 'transcribeStream',
                    text: '',
                    done: true
                };
            }
        })
    },
    logging: {
        module: asrAddonLogging,
        namespace: ADDON_ASR
    }
});
